window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7ace280160bb3028"]={"versions": [{"id": "FIG-7ace280160bb3028", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Diagnose-Extrakts (Diagnostic Extract Template). Es modelliert die statische Struktur und Metamodell-Beziehungen für den UDS-Diagnosedienst RequestUpload (Service-Identifier 0x35) und dessen Einbettung in die generischen Diagnose-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticCommonElement</code>: Allgemeine Basisklasse (angegeben als Stereotyp/Header bei mehreren Modellelementen).\n</li><li><code>DiagnosticServiceInstance</code>: Abstrakte Basisklasse für Diagnose-Service-Instanzen mit Assoziation <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«atpAbstract»</code>) zu <code>DiagnosticServiceClass</code> sowie einer Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticAccessPermission</code>.\n</li><li><code>DiagnosticMemoryByAddress</code>: Spezialisierung von <code>DiagnosticServiceInstance</code>.\n</li><li><code>DiagnosticMemoryAddressableRangeAccess</code>: Spezialisierung von <code>DiagnosticMemoryByAddress</code>.\n</li><li><code>DiagnosticRequestUpload</code>: Konkrete Service-Instanzklasse für den Dienst RequestUpload (0x35), erbt von <code>DiagnosticMemoryAddressableRangeAccess</code>. Sie besitzt eine gerichtete Assoziation <code>+requestUploadClass</code> mit Multiplizität <code>1</code> und der Eigenschaft <code>{redefines serviceClass}</code> zur Klasse <code>DiagnosticRequestUploadClass</code>.\n</li><li><code>DiagnosticServiceClass</code>: Basisklasse für Service-Klassen mit dem Attribut <code>+ accessPermissionValidity :DiagnosticAccessPermissionValidityEnum</code> und einer Assoziation <code>+accessPermission</code> mit Multiplizität <code>0..1</code> zu <code>DiagnosticAccessPermission</code>.\n</li><li><code>DiagnosticRequestUploadClass</code>: Spezialisierung von <code>DiagnosticServiceClass</code> zur spezifischen Konfiguration des RequestUpload-Dienstes.\n</li><li><code>DiagnosticAccessPermission</code>: Metaklasse zur Definition von Zugriffsrechten für Diagnoseinstanzen und Serviceklassen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert Deklarations- und Konfigurationsstrukturen für Instanziierung, Klassenzuordnung und Zugriffsberechtigungsvalidierung des Upload-Dienstes im AUTOSAR-Diagnose-Framework.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert verbindliche Metamodell-Vorgaben für AUTOSAR-DEXT-Autoren und Konfigurationswerkzeuge. Eine Instanz von <code>DiagnosticRequestUpload</code> muss genau eine zugeordnete <code>DiagnosticRequestUploadClass</code> referenzieren (<code>1</code>), wodurch die geerbte abstrakte Assoziation <code>serviceClass</code> redefiniert wird. Zugriffsberechtigungen können sowohl auf Instanz- als auch auf Klassenebene über <code>DiagnosticAccessPermission</code> mit Gültigkeitsdefinition via <code>DiagnosticAccessPermissionValidityEnum</code> verankert werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8780f94670d78d2b", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Diagnose-Extrakts (Diagnostic Extract Template). Es modelliert die statische Struktur und Metamodell-Beziehungen für den UDS-Diagnosedienst RequestUpload (Service-Identifier 0x35) und dessen Einbettung in die generischen Diagnose-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticCommonElement</code>: Allgemeine Basisklasse (angegeben als Stereotyp/Header bei mehreren Modellelementen).\n</li><li><code>DiagnosticServiceInstance</code>: Abstrakte Basisklasse für Diagnose-Service-Instanzen mit Assoziation <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«atpAbstract»</code>) zu <code>DiagnosticServiceClass</code> sowie einer Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticAccessPermission</code>.\n</li><li><code>DiagnosticMemoryByAddress</code>: Spezialisierung von <code>DiagnosticServiceInstance</code>.\n</li><li><code>DiagnosticMemoryAddressableRangeAccess</code>: Spezialisierung von <code>DiagnosticMemoryByAddress</code>.\n</li><li><code>DiagnosticRequestUpload</code>: Konkrete Service-Instanzklasse für den Dienst RequestUpload (0x35), erbt von <code>DiagnosticMemoryAddressableRangeAccess</code>. Sie besitzt eine gerichtete Assoziation <code>+requestUploadClass</code> mit Multiplizität <code>1</code> und der Eigenschaft <code>{redefines serviceClass}</code> zur Klasse <code>DiagnosticRequestUploadClass</code>.\n</li><li><code>DiagnosticServiceClass</code>: Basisklasse für Service-Klassen mit dem Attribut <code>+ accessPermissionValidity :DiagnosticAccessPermissionValidityEnum</code> und einer Assoziation <code>+accessPermission</code> mit Multiplizität <code>0..1</code> zu <code>DiagnosticAccessPermission</code>.\n</li><li><code>DiagnosticRequestUploadClass</code>: Spezialisierung von <code>DiagnosticServiceClass</code> zur spezifischen Konfiguration des RequestUpload-Dienstes.\n</li><li><code>DiagnosticAccessPermission</code>: Metaklasse zur Definition von Zugriffsrechten für Diagnoseinstanzen und Serviceklassen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert Deklarations- und Konfigurationsstrukturen für Instanziierung, Klassenzuordnung und Zugriffsberechtigungsvalidierung des Upload-Dienstes im AUTOSAR-Diagnose-Framework.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert verbindliche Metamodell-Vorgaben für AUTOSAR-DEXT-Autoren und Konfigurationswerkzeuge. Eine Instanz von <code>DiagnosticRequestUpload</code> muss genau eine zugeordnete <code>DiagnosticRequestUploadClass</code> referenzieren (<code>1</code>), wodurch die geerbte abstrakte Assoziation <code>serviceClass</code> redefiniert wird. Zugriffsberechtigungen können sowohl auf Instanz- als auch auf Klassenebene über <code>DiagnosticAccessPermission</code> mit Gültigkeitsdefinition via <code>DiagnosticAccessPermissionValidityEnum</code> verankert werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-51153e15b508c57d", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Diagnose-Extrakts (Diagnostic Extract Template). Es modelliert die statische Struktur und Metamodell-Beziehungen für den UDS-Diagnosedienst RequestUpload (Service-Identifier 0x35) und dessen Einbettung in die generischen Diagnose-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticCommonElement</code>: Allgemeine Basisklasse (angegeben als Stereotyp/Header bei mehreren Modellelementen).\n</li><li><code>DiagnosticServiceInstance</code>: Abstrakte Basisklasse für Diagnose-Service-Instanzen mit Assoziation <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«atpAbstract»</code>) zu <code>DiagnosticServiceClass</code> sowie einer Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticAccessPermission</code>.\n</li><li><code>DiagnosticMemoryByAddress</code>: Spezialisierung von <code>DiagnosticServiceInstance</code>.\n</li><li><code>DiagnosticMemoryAddressableRangeAccess</code>: Spezialisierung von <code>DiagnosticMemoryByAddress</code>.\n</li><li><code>DiagnosticRequestUpload</code>: Konkrete Service-Instanzklasse für den Dienst RequestUpload (0x35), erbt von <code>DiagnosticMemoryAddressableRangeAccess</code>. Sie besitzt eine gerichtete Assoziation <code>+requestUploadClass</code> mit Multiplizität <code>1</code> und der Eigenschaft <code>{redefines serviceClass}</code> zur Klasse <code>DiagnosticRequestUploadClass</code>.\n</li><li><code>DiagnosticServiceClass</code>: Basisklasse für Service-Klassen mit dem Attribut <code>+ accessPermissionValidity :DiagnosticAccessPermissionValidityEnum</code> und einer Assoziation <code>+accessPermission</code> mit Multiplizität <code>0..1</code> zu <code>DiagnosticAccessPermission</code>.\n</li><li><code>DiagnosticRequestUploadClass</code>: Spezialisierung von <code>DiagnosticServiceClass</code> zur spezifischen Konfiguration des RequestUpload-Dienstes.\n</li><li><code>DiagnosticAccessPermission</code>: Metaklasse zur Definition von Zugriffsrechten für Diagnoseinstanzen und Serviceklassen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert Deklarations- und Konfigurationsstrukturen für Instanziierung, Klassenzuordnung und Zugriffsberechtigungsvalidierung des Upload-Dienstes im AUTOSAR-Diagnose-Framework.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert verbindliche Metamodell-Vorgaben für AUTOSAR-DEXT-Autoren und Konfigurationswerkzeuge. Eine Instanz von <code>DiagnosticRequestUpload</code> muss genau eine zugeordnete <code>DiagnosticRequestUploadClass</code> referenzieren (<code>1</code>), wodurch die geerbte abstrakte Assoziation <code>serviceClass</code> redefiniert wird. Zugriffsberechtigungen können sowohl auf Instanz- als auch auf Klassenebene über <code>DiagnosticAccessPermission</code> mit Gültigkeitsdefinition via <code>DiagnosticAccessPermissionValidityEnum</code> verankert werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8a43c399e34c2f82", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Diagnose-Extrakts (Diagnostic Extract Template). Es modelliert die statische Struktur und Metamodell-Beziehungen für den UDS-Diagnosedienst RequestUpload (Service-Identifier 0x35) und dessen Einbettung in die generischen Diagnose-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticCommonElement</code>: Allgemeine Basisklasse (als Header/Stereotyp angegeben).\n</li><li><code>DiagnosticServiceInstance</code>: Abstrakte Basisklasse für Diagnose-Service-Instanzen mit Assoziation <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«atpAbstract»</code>) zu <code>DiagnosticServiceClass</code> sowie einer Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticAccessPermission</code>.\n</li><li><code>DiagnosticMemoryByAddress</code>: Spezialisierung von <code>DiagnosticServiceInstance</code>.\n</li><li><code>DiagnosticMemoryAddressableRangeAccess</code>: Spezialisierung von <code>DiagnosticMemoryByAddress</code>.\n</li><li><code>DiagnosticRequestUpload</code>: Konkrete Service-Instanzklasse für den RequestUpload-Dienst, erbt von <code>DiagnosticMemoryAddressableRangeAccess</code>. Sie besitzt eine gerichtete Assoziation <code>+requestUploadClass</code> mit Multiplizität <code>0..1</code> und der Eigenschaft <code>{redefines serviceClass}</code> zur Klasse <code>DiagnosticRequestUploadClass</code>.\n</li><li><code>DiagnosticServiceClass</code>: Basisklasse für Service-Klassen ohne eigene Attribute oder Assoziationen zu Zugriffsberechtigungen.\n</li><li><code>DiagnosticRequestUploadClass</code>: Spezialisierung von <code>DiagnosticServiceClass</code>.\n</li><li><code>DiagnosticAccessPermission</code>: Metaklasse für Zugriffsberechtigungen, die von <code>DiagnosticServiceInstance</code> referenziert wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert Deklarations- und Konfigurationsstrukturen für Instanziierung, Klassenzuordnung und Zugriffsberechtigungsvalidierung des Upload-Dienstes im AUTOSAR-Diagnose-Framework.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert verbindliche Metamodell-Vorgaben für AUTOSAR-DEXT-Autoren und Konfigurationswerkzeuge. Eine <code>DiagnosticRequestUpload</code>-Instanz kann optional (<code>0..1</code>) eine <code>DiagnosticRequestUploadClass</code> referenzieren, wodurch <code>serviceClass</code> redefiniert wird. Zugriffsberechtigungen werden über <code>DiagnosticServiceInstance</code> konfiguriert; auf Klassenebene existieren in <code>DiagnosticServiceClass</code> keine direkten Zugriffs- oder Validierungsattribute mehr.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7ace280160bb3028", "to": "FIG-8780f94670d78d2b", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8780f94670d78d2b", "to": "FIG-51153e15b508c57d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Attribut <code>+ accessPermissionValidity</code> in <code>DiagnosticServiceClass</code>: Leerzeichen nach dem Doppelpunkt zur Typangabe eingefügt (<code>: DiagnosticAccessPermissionValidityEnum</code>).\n</li><li>Assoziation <code>+requestUploadClass</code>: Beschriftungsplatzierung leicht angepasst.\n</li></ul>"}, {"from": "FIG-51153e15b508c57d", "to": "FIG-8a43c399e34c2f82", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Klasse <code>DiagnosticServiceClass</code>: Attribut <code>+ accessPermissionValidity : DiagnosticAccessPermissionValidityEnum</code> entfernt.\n</li><li>Klasse <code>DiagnosticServiceClass</code>: Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticAccessPermission</code> entfernt.\n</li><li>Assoziation <code>+requestUploadClass</code> von <code>DiagnosticRequestUpload</code> zu <code>DiagnosticRequestUploadClass</code>: Kardinalität von <code>1</code> auf <code>0..1</code> geändert.\n</li></ul>"}]};
